#define main legacy_main
#include "gamma-correction-cuda/main.cu"
#undef main
#include <vector>
int main(){int n=4096,repeat=10;std::vector<ImgPixel>input(n),expected(n),output(n);for(int i=0;i<n;i++){input[i].set((17*i+3)%256,(31*i+7)%256,(13*i+19)%256,(7*i)%256);auto q=input[i];float v=(.3f*q.r+.59f*q.g+.11f*q.b)/255.f;uint8_t x=uint8_t(255.f*v*v);expected[i].set(x,x,x,x);}ImgPixel*d;cudaMalloc(&d,n*sizeof(ImgPixel));cudaMemcpy(d,input.data(),n*4,cudaMemcpyHostToDevice);gamma_correction<<<n/256,256>>>(d);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;
for(int trial=1;trial<=5;trial++){double total=0.;for(int j=0;j<repeat;j++){cudaMemcpy(d,input.data(),n*4,cudaMemcpyHostToDevice);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();gamma_correction<<<n/256,256>>>(d);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();}cudaMemcpy(output.data(),d,n*4,cudaMemcpyDeviceToHost);bool correct=output==expected;char file[32];snprintf(file,sizeof(file),"trial_%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,n,f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.14g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%d,\"timing_region\":\"mean_individually_synchronized_kernel_excluding_reset\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint8\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,total/repeat,correct?"true":"false",4*n,correct?0:255,repeat,file,4*n);if(!correct)return 1;}cudaFree(d);}
